            for (var i=0;i<actual.Length;i++) if (actual[i].ParameterType != parameters[i] || actual[i].IsOptional || actual[i].IsOut != parameters[i].IsByRef) throw new MissingMethodException(name);
            try { return method.Invoke(target,arguments); }
            catch (TargetInvocationException error) { if (error.InnerException != null) throw error.InnerException; throw; }
        }
