        internal ConfirmedProfileResetRequestV1 ConfirmActual(object result)
        {
            if (Read(result,Hub("NewGameConfirmationStartResultV1"),"Outcome",Hub("NewGameConfirmationOutcomeV1")).ToString() == "DecisionRequired")
            {
                var decision=Read(result,Hub("NewGameConfirmationStartResultV1"),"DecisionCapability",Hub("NewGameDecisionCapabilityV1"));
                result=Invoke(Owner,Hub("NewGameConfirmationOwnerV1"),"Confirm",Hub("NewGameConfirmationStartResultV1"),new[] {Hub("NewGameDecisionCapabilityV1")},decision);
            }
            Assert.That(Read(result,Hub("NewGameConfirmationStartResultV1"),"Outcome",Hub("NewGameConfirmationOutcomeV1")).ToString(),Is.EqualTo("Confirmed"));
            return (ConfirmedProfileResetRequestV1)Read(result,Hub("NewGameConfirmationStartResultV1"),"ConfirmedRequest",typeof(ConfirmedProfileResetRequestV1));
        }
        internal void SelectInitialNewGame()
        {
            Publish(); PresenterFixed();
            Publish(Key.DownArrow);
            Assert.That(Router.CurrentUiFrame.Value.NavigateChanged,Is.True);
            Assert.That(Router.CurrentUiFrame.Value.NavigateYQ4096,Is.LessThan(0));
            PresenterFixed(); Publish(); PresenterFixed();
            Publish(Key.Enter); Assert.That(Router.CurrentUiFrame.Value.SubmitPressed,Is.True); PresenterFixed();
            Lifecycle(HandoffOwner,"LateUpdate");
            Assert.That(Read(HandoffOwner,Hub("HubMenuIntentHandoffOwnerV1"),"State",Hub("HubMenuIntentHandoffOwnerStateV1")).ToString(),Is.EqualTo("RequestReady"));
            var requestType=Hub("HubMenuIntentRequestV1");
            var request=Field(HandoffOwner,Hub("HubMenuIntentHandoffOwnerV1"),"_request",typeof(Nullable<>).MakeGenericType(requestType));
            Assert.That(request,Is.Not.Null); Assert.That(request.GetType(),Is.EqualTo(requestType));
            Assert.That(Field(request,requestType,"_item",typeof(HubMenuItemV1)),Is.EqualTo(HubMenuItemV1.NewGame));
            // Enter는 해제하지 않는다. C2의 실제 canceled 관찰 시험이 같은 입력을 보존한다.
        }
