                if (Convert.ToInt32(Read(f.Presenter,Hub("HubMenuPresenterV1"),"State",Hub("HubPresenterStateV1"))) == 0) Lifecycle(f.Presenter,"Awake");
                if (Convert.ToInt32(Read(f.HandoffOwner,Hub("HubMenuIntentHandoffOwnerV1"),"State",Hub("HubMenuIntentHandoffOwnerStateV1"))) == 0) Lifecycle(f.HandoffOwner,"Awake");
                Lifecycle(f.Adapter,"Start"); Lifecycle(latch,"Start"); Lifecycle(latch,"Update");
                f.Router.StepForTests(); Lifecycle(f.Presenter,"Update");
