                    var closed=(bool)OriginalField(original,halfType,"Closed",typeof(bool));
                    var blocked=(bool)OriginalField(original,halfType,"Blocked",typeof(bool));
                    if (ReferenceEquals(original,current))
                    { Assert.That(Field(receiver,declaring,"_executionGuardClosed",typeof(bool)),Is.EqualTo(closed)); Assert.That(Field(receiver,declaring,"_executionGuardBlocked",typeof(bool)),Is.EqualTo(blocked)); }
