        private static void AssertFrozenOrdinaryWriterSource()
        {
            var project=System.IO.Path.GetDirectoryName(Application.dataPath);
            const string savePath="Assets/AcadeGameMaker/Runtime/Profile/ProfileAtomicSaveServiceV1.cs";
            const string barrierPath="Assets/AcadeGameMaker/Runtime/Profile/ProfileNewGameResetServiceV1.cs";
            var paths=new[] {savePath,barrierPath};
            var hashes=new[] {"80DDBF925C74A8A81DD3B3950F25B3843D76B81F62ED942F3F3585CFB52B3F87","23D7248B1A603A89BC8FF0FFDBB24FA04E640A66018DDC5689F97EC80701FBE5"};
            var manifest=JsonUtility.FromJson<FrozenSourceManifest>(File.ReadAllText(System.IO.Path.Combine(project,"artifacts/c4-frozen-source-manifest-v1.json")));
            Assert.That(manifest,Is.Not.Null); Assert.That(manifest.SchemaVersion,Is.EqualTo(1)); Assert.That(manifest.Files,Is.Not.Null);
            Assert.That(manifest.Count,Is.EqualTo(manifest.Files.Length)); Assert.That(manifest.WholeAccepted,Is.False);
            var texts=new string[2];
            for (var i=0;i<paths.Length;i++)
            {
                FrozenSourceBinding found=null;
                foreach (var binding in manifest.Files) if (binding.Path == paths[i]) { Assert.That(found,Is.Null); found=binding; }
                Assert.That(found,Is.Not.Null); Assert.That(found.Kind,Is.EqualTo("Runtime")); Assert.That(found.Sha256,Is.EqualTo(hashes[i]));
                var bytes=File.ReadAllBytes(System.IO.Path.Combine(project,paths[i]));
                using (var sha=System.Security.Cryptography.SHA256.Create()) Assert.That(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-",""),Is.EqualTo(found.Sha256));
                texts[i]=System.Text.Encoding.UTF8.GetString(bytes).Replace("\r\n","\n");
            }
            Assert.That(texts[0].Contains("using (ProfileRootOperationLockV1.Acquire(normalized))\n            {\n                ProfileResetBarrierV1.ThrowIfPresent(normalized);\n                return Save(normalized, document, ProfileAtomicSaveBclFileOperations.Instance);"),Is.True);
            Assert.That(texts[1].Contains("var attributes = File.GetAttributes(path);"),Is.True);
        }
