        private static Tuple<string,string> FrozenNoSameCaseSavePointers(bool preC1=false,string fixtureMethod=null)
        {
            var project=System.IO.Path.GetDirectoryName(Application.dataPath);
            const string parent="Assets/AcadeGameMaker/Tests/PlayMode/InputUnity/ProfileResetExecutionBridgePlayModeTests.cs";
            const string fixture="Assets/AcadeGameMaker/Tests/PlayMode/InputUnity/C4ActualExecutionPlayFixtureV1.cs";
            var manifest=JsonUtility.FromJson<FrozenSourceManifest>(File.ReadAllText(System.IO.Path.Combine(project,"artifacts/c4-frozen-source-manifest-v17.json")));
            Assert.That(manifest,Is.Not.Null); Assert.That(manifest.Files,Is.Not.Null);
            string[] paths={parent,fixture}; var pointers=new string[2];
            for(var p=0;p<paths.Length;p++)
            {
                FrozenSourceBinding binding=null;
                foreach(var candidate in manifest.Files) if(candidate.Path == paths[p]) { Assert.That(binding,Is.Null); binding=candidate; }
                Assert.That(binding,Is.Not.Null);
                var bytes=File.ReadAllBytes(System.IO.Path.Combine(project,paths[p]));
                using(var sha=System.Security.Cryptography.SHA256.Create()) Assert.That(BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-",""),Is.EqualTo(binding.Sha256));
                var lines=File.ReadAllLines(System.IO.Path.Combine(project,paths[p])); var line=0;
                var needle=p==0 ? "public void "+TestContext.CurrentContext.Test.MethodName+"(" :
                    preC1 ? "try { File.GetAttributes(System.IO.Path.Combine(Root,\"profile.reset.json\")); marker=true; }" :
                    "try { File.GetAttributes(System.IO.Path.Combine(Root,\"profile.reset.json\")); barrierPresent=true; }";
                var first=0; var last=lines.Length;
                if(p==1)
                {
                    var declaration=fixtureMethod != null ? "internal void "+fixtureMethod+"(" :
                        preC1 ? "internal void ObservePreC1Failure(" :
                        "internal void ObserveActualBarrier(EvidenceRow row,ProfileResetExecutionResultV1 actualResult,RootLeaseWorker actualWorker,ConfirmedProfileResetRequestV1 actualConfirmed)";
                    first=-1;
                    for(var i=0;i<lines.Length;i++) if(lines[i].TrimStart().StartsWith(declaration,StringComparison.Ordinal)) { Assert.That(first,Is.EqualTo(-1)); first=i; }
                    Assert.That(first,Is.GreaterThanOrEqualTo(0));
                    for(var i=first+1;i<lines.Length;i++)
                        if(lines[i].StartsWith("        internal ",StringComparison.Ordinal) || lines[i].StartsWith("        private ",StringComparison.Ordinal)) { last=i; break; }
                }
                for(var i=first;i<last;i++) if(lines[i].TrimStart().StartsWith(needle,StringComparison.Ordinal)) { Assert.That(line,Is.Zero); line=i+1; }
                Assert.That(line,Is.GreaterThan(0)); pointers[p]="source:"+paths[p]+":"+line;
                if(p==0)
                {
                    var start=line-1; var next=lines.Length;
                    for(var i=start+1;i<lines.Length;i++)
                        if(lines[i].TrimStart().StartsWith("public void ",StringComparison.Ordinal)) { next=i; break; }
                    var body=string.Join(Environment.NewLine,lines,start,next-start);
                    Assert.That(body.Contains("ProfileAtomicSaveServiceV1.Save("),Is.False);
                }
            }
            return Tuple.Create(pointers[0],pointers[1]);
        }
