        internal sealed class RootLeaseWorker : IDisposable
        {
            private readonly ManualResetEventSlim _ready=new ManualResetEventSlim(false), _release=new ManualResetEventSlim(false);
            private readonly Thread _worker;
            private Exception _failure;
            internal bool LeaseReleased, Joined;
            private bool _releaseWasSignaled;
            internal bool ReleaseSignaled { get { return _releaseWasSignaled; } }
            internal RootLeaseWorker(string root)
            {
                var type=ProfileType("ProfileRootOperationLockV1");
                var acquire=type.GetMethod("Acquire",BindingFlags.DeclaredOnly|BindingFlags.Static|BindingFlags.NonPublic,null,new[] {typeof(string)},null);
                if (acquire == null || acquire.DeclaringType != type || acquire.ReturnType != type || acquire.IsGenericMethod)
                    throw new MissingMethodException("Exact actual root lease binding failed.");
                _worker=new Thread(()=>
                {
                    IDisposable lease=null;
                    try
                    {
                        lease=(IDisposable)acquire.Invoke(null,new object[] {root}); _ready.Set();
                        if (!_release.Wait(TimeSpan.FromSeconds(60))) throw new TimeoutException("실제 root 작업자의 해제 신호가 없었습니다.");
                    }
                    catch (Exception error) { _failure=error; _ready.Set(); }
                    finally { try { if (lease != null) { lease.Dispose(); LeaseReleased=true; } } catch (Exception error) { _failure=error; } }
                });
                _worker.IsBackground=true; _worker.Start();
                try { if (!_ready.Wait(TimeSpan.FromSeconds(10))) throw new TimeoutException("실제 root lease 준비 제한 시간을 넘었습니다."); if (_failure != null) throw _failure; }
                catch { Dispose(); throw; }
            }
            public void Dispose()
            {
                _release.Set(); _releaseWasSignaled=_release.IsSet; Joined=_worker.Join(TimeSpan.FromSeconds(10));
                if (!Joined) throw new TimeoutException("실제 root 작업자 종료를 수거하지 못했습니다.");
                _ready.Dispose(); _release.Dispose();
                if (_failure != null) throw _failure;
            }
        }
