                "guard.adapter","guard.router","guard.permanentFaultRecorded","barrier.state","barrier.ordinaryWriterBlocked","barrier.evidenceReference",
                "history.originalCommitPreserved","history.originalEpochPreserved","history.oldTakePreserved","history.oldCursorPreserved","history.receiptReferencePreserved",
                "cleanup.required","cleanup.releaseSignaled","cleanup.workerLeaseReleased","cleanup.workerJoined","cleanup.originalThreadCleanup","cleanup.exception",
