                _kind=kind; _family=checkpointFamily; _checkpoint=checkpointName; _checkpointValue=checkpointValue;
                foreach (var key in CanonicalKeys)
                {
                    var value=key.EndsWith("Generation",StringComparison.Ordinal) || key.StartsWith("callCounts.",StringComparison.Ordinal) || key.EndsWith(".evidenceReference",StringComparison.Ordinal) || key.EndsWith(".exception",StringComparison.Ordinal) ? null :
                        key.EndsWith(".checked",StringComparison.Ordinal) || key == "cleanup.required" ? (object)false : "Unknown";
                    Put(key,value,"Unknown",null);
