            internal void Observe(string path,object actual,string certainty="Observed",string evidenceReference=null)
            {
                if (_ended) throw new InvalidOperationException("종료한 관측 행은 변경할 수 없습니다.");
                if (actual is int) actual=(long)(int)actual;
                if (actual != null && !(actual is string) && !(actual is bool) && !(actual is long)) throw new ArgumentException("관측 leaf는 문자열·bool·Int64·null만 허용합니다.");
                if (certainty != "Observed" && certainty != "SourceEstablished" && certainty != "Unknown") throw new ArgumentException("정확 certainty가 아닙니다.");
                if (System.Array.IndexOf(CanonicalKeys,path)<0)
                {
