            private void Emit(string status,bool reached,string failure)
            {
                var facts=new System.Collections.Generic.List<object>();
                foreach (var key in CanonicalKeys) facts.Add(_facts[key]);
                foreach (var key in _diagnostics) facts.Add(_facts[key]);
                var snapshot=new System.Collections.Generic.Dictionary<string,object>{{"snapshotSha256",null},{"facts",facts}};
                var row=new System.Collections.Generic.Dictionary<string,object>{{"id",_id},{"schemaVersion",1L},{"requirementIds",Strings(_requirements)},{"acceptanceIds",Strings(_acceptance)},
                    {"expectedCase",_case},{"status",status},{"actualEvidenceKind",_kind},{"checkpointFamily",_family},{"checkpointName",_checkpoint},{"checkpointValue",_checkpointValue.HasValue ? (object)(long)_checkpointValue.Value : null},
                    {"outcome",Outcome},{"phase",Phase},{"applicability",Applicability},{"reached",reached},
                    {"before",new System.Collections.Generic.Dictionary<string,object>{{"snapshotSha256",null},{"facts",new System.Collections.Generic.List<object>()}}},{"after",snapshot},
                    {"callCounts",_calls},{"authorityCorrelation",_authority},{"guard",_guard},{"barrier",_barrier},{"history",_history},{"cleanup",_cleanup},{"failureReason",failure}};
                TestContext.Out.WriteLine(WriteJson(row));
            }
            private static System.Collections.Generic.List<object> Strings(string[] values)
            { var result=new System.Collections.Generic.List<object>(); foreach(var value in values) result.Add(value); return result; }
            private static string WriteJson(object value)
            {
                if (value == null) return "null";
                var text=value as string;
                if (text != null)
                {
                    var output=new System.Text.StringBuilder("\"");
                    foreach(var character in text)
                    { if(character=='"'||character=='\\') output.Append('\\').Append(character); else if(character<32) output.Append("\\u").Append(((int)character).ToString("x4",System.Globalization.CultureInfo.InvariantCulture)); else output.Append(character); }
                    return output.Append('"').ToString();
                }
                if (value is bool || value is long) return Canonical(value);
                var dictionary=value as System.Collections.Generic.Dictionary<string,object>;
                if (dictionary != null)
                {
                    var keys=new System.Collections.Generic.List<string>(dictionary.Keys); keys.Sort(StringComparer.Ordinal);
                    if (dictionary.ContainsKey("id")) { keys.Remove("id"); keys.Insert(0,"id"); }
                    var entries=new System.Collections.Generic.List<string>(); foreach(var key in keys) entries.Add(WriteJson(key)+":"+WriteJson(dictionary[key]));
                    return "{"+string.Join(",",entries.ToArray())+"}";
                }
                var array=value as System.Collections.Generic.List<object>;
                if(array != null) { var items=new System.Collections.Generic.List<string>(); foreach(var item in array) items.Add(WriteJson(item)); return "["+string.Join(",",items.ToArray())+"]"; }
